using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
namespace OceanariumFishing.Editor
{
    public static class AquariumBuildChecks
    {
        static readonly List<string> results=new();static AquariumBuilding b;static string owner;static bool running;
        static void Check(bool condition,string message){results.Add((condition?"PASS: ":"FAIL: ")+message);if(!condition)throw new InvalidOperationException(message);}
        static string Cmd()=>Guid.NewGuid().ToString("N");
        public static void Run(){if(running||!EditorApplication.isPlaying)return;b=UnityEngine.Object.FindFirstObjectByType<AquariumBuilding>();owner=b.World.Data.ownerId;running=true;results.Clear();GameSession.Current.StartCoroutine(Guard());}
        static IEnumerator Guard(){var iter=Steps();bool pass=true;while(true){object value=null;bool next=false;try{next=iter.MoveNext();if(next)value=iter.Current;}catch(Exception e){results.Add(e.ToString());Debug.LogException(e);pass=false;break;}if(!next)break;yield return value;}File.WriteAllText("Docs/ASTRA_06_TEST_RESULTS.txt",(pass?"PASS ":"FAIL ")+DateTime.UtcNow.ToString("O")+"\n"+string.Join("\n",results));running=false;}
        static string Buy(string type)
        {var old=b.Layout.objects.FirstOrDefault(o=>o.typeId==type);if(old!=null)return old.id;string command=Cmd();int coins=b.World.Save.coins;bool ok=b.Buy(owner,command,b.Layout.revision,type,out var id,out var why);Check(ok,"Purchase "+type+": "+why);Check(b.World.Save.coins==coins-b.Item(type).price,"Exact wallet charge: "+type);int after=b.World.Save.coins;Check(!b.Buy(owner,command,b.Layout.revision,type,out _,out _)&&b.World.Save.coins==after,"Replay cannot duplicate purchase or charge");return id;}
        static void Place(string id,Vector3 p,float angle=0,string tank=null){Check(b.PlaceObject(owner,Cmd(),b.Layout.revision,id,p,angle,tank,out var why),"Place "+b.Object(id).typeId+" at "+p+": "+why);}
        static Vector3 Find(string id,float minZ=5.8f,float angle=0)
        {var o=b.Object(id);for(float z=minZ;z<4.5f+(b.Layout.level-1)*8;z+=.5f)for(float x=-4.5f;x<=4.5f;x+=.5f){var candidate=JsonUtility.FromJson<AquariumLayoutObject>(JsonUtility.ToJson(o));candidate.stored=false;candidate.position=new(x,0,z);candidate.rotation=angle;if(b.Validate(b.Layout,candidate)==null)return candidate.position;}throw new Exception("No valid candidate for "+o.typeId);}
        static IEnumerator Steps()
        {
            Check(b.Ready,"Existing museum and layout migration ready");Check(b.catalog.items.Count(i=>i.category==BuildCategory.Tanks)==8,"Eight tank geometries");Check(b.catalog.items.Count(i=>i.category==BuildCategory.Plants)==10,"Ten plant models");Check(b.catalog.items.Count(i=>i.category==BuildCategory.Corals||i.category==BuildCategory.Decorations)==12,"Twelve aquatic decorations");Check(b.catalog.items.Count(i=>i.category==BuildCategory.Furniture)==15,"Fifteen furniture prefabs");
            Check(b.catalog.items.Where(i=>i.category!=BuildCategory.Expansions).All(i=>i.prefab&&i.thumbnail),"Catalog prefabs and thumbnails assigned");Check(b.Navigation.Validate(b.Layout),"Original layout preserves visitor access");
            string fishBefore=string.Join("|",b.World.Data.kept.Select(f=>f.instanceId).OrderBy(s=>s));b.UI.Open();yield return new WaitForSeconds(.5f);Check(b.UI.IsOpen,"Build mode opens");ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_06_BuildCatalog.png");
            b.World.Collect(out _);if(b.Layout.level==1)Check(b.Buy(owner,Cmd(),b.Layout.revision,"expansion_1",out _,out var why),"Purchase expanded exhibit hall: "+why);Check(b.Layout.level>=2,"Room expansion saved");Check(b.Navigation.Validate(b.Layout),"Navigation connected through new room");
            string small=Buy("tank_0");Place(small,Find(small));var original=b.Object(small).position;Place(small,Find(small,6.3f,90),90);Check(b.Object(small).rotation==90,"Tank rotation saved");
            int revision=b.Layout.revision;Check(!b.PlaceObject(owner,Cmd(),revision,small,new Vector3(0,0,-4),0,null,out _),"Entrance placement rejected");Check(!b.PlaceObject(owner,Cmd(),revision,small,new Vector3(99,0,0),0,null,out _),"Outside placement rejected");Check(!b.PlaceObject("wrong-owner",Cmd(),revision,small,original,0,null,out _),"Foreign owner rejected");Check(!b.StoreObject(owner,Cmd(),revision-1,small,out _),"Stale revision rejected");
            var other=b.Layout.objects.First(o=>o.id!=small&&!o.stored&&b.IsTank(o));Check(!b.PlaceObject(owner,Cmd(),revision,small,other.position,0,null,out _),"Tank overlap rejected");
            string round=Buy("tank_3");Place(round,Find(round,7.5f));string bench=Buy("furniture_0");Place(bench,Find(bench,9));Check(b.Navigation.Validate(b.Layout),"Routes remain after mixed layout edits");
            if(!b.Layout.purchases.Contains("sub_3"))Check(b.Buy(owner,Cmd(),b.Layout.revision,"sub_3",out _,out _),"Buy golden sand");Check(b.Style(owner,Cmd(),b.Layout.revision,"sub_3",small,out _),"Substrate applied to selected tank");
            string plant=Buy("plant_8");Place(plant,new Vector3(-.4f,0,0),0,small);string coral=Buy("decor_0");Place(coral,new Vector3(.3f,0,0),30,small);Check(!b.PlaceObject(owner,Cmd(),b.Layout.revision,coral,new Vector3(4,0,0),0,small,out _),"Glass boundary rejects decoration");Check(!b.PlaceObject(owner,Cmd(),b.Layout.revision,coral,new Vector3(-.4f,0,0),0,small,out _),"Decoration overlap rejected");float score=b.DecorationScore(b.Layout);Check(b.StoreObject(owner,Cmd(),b.Layout.revision,coral,out _),"Remove decoration");Place(coral,new Vector3(.3f,0,0),30,small);Check(Mathf.Abs(score-b.DecorationScore(b.Layout))<.001f,"Remove/replace cannot farm popularity");
            var t=b.World.Tanks.First(t=>t.id==small);var specimen=b.World.Data.kept.FirstOrDefault(f=>b.World.Validate(f,t)==null);if(specimen==null){var existing=b.World.Data.kept.FirstOrDefault(f=>f.ownership==FishOwnership.Displayed&&f.length<t.definition.maxLength);if(existing!=null){b.World.Remove(owner,existing.instanceId,out _);specimen=b.World.Data.kept.First(f=>f.instanceId==existing.instanceId);}}
            Check(specimen!=null,"Existing genuinely caught compatible specimen available");Check(b.World.Place(owner,specimen.instanceId,small,out _),"Place caught specimen in purchased tank");yield return new WaitForSeconds(.3f);string fishId=specimen.instanceId;var current=b.Object(small).position;Place(small,Find(small,6.3f),0);Check(b.World.Data.kept.First(f=>f.instanceId==fishId).tankId==small,"Moving tank retains fish identity and assignment");
            for(int n=0;n<30;n++){yield return new WaitForSeconds(.1f);foreach(var f in t.Fish)Check(b.SafeFishPoint(t,f.transform.localPosition,.18f),"Fish avoids placed interior obstacles");}
            Check(b.StoreObject(owner,Cmd(),b.Layout.revision,small,out _),"Store occupied tank safely");Check(b.World.Data.kept.First(f=>f.instanceId==fishId).ownership==FishOwnership.Stored,"Stored tank returns fish to owner's inventory");Place(small,Find(small,6.3f),0);Check(b.World.Place(owner,fishId,small,out _),"Restore same specimen without duplication");
            foreach(var style in new[]{"floor_4","wall_3"}){if(!b.Layout.purchases.Contains(style))Check(b.Buy(owner,Cmd(),b.Layout.revision,style,out _,out _),"Purchase "+style);Check(b.Style(owner,Cmd(),b.Layout.revision,style,null,out _),"Apply "+style);}
            Check(string.Join("|",b.World.Data.kept.Select(f=>f.instanceId).OrderBy(s=>s))==fishBefore,"All original fish identities preserved");Check(b.Layout.objects.Select(o=>o.id).Distinct().Count()==b.Layout.objects.Count,"Unique object IDs");var saved=FishCollectionStore.Load();Check(JsonUtility.ToJson(saved.aquarium.layout)==JsonUtility.ToJson(b.Layout),"Layout atomic save/load round trip");Check(saved.aquarium.coins==b.World.Save.coins,"Wallet matches persisted layout transactions");File.WriteAllText("Temp/ASTRA06_expected.json",JsonUtility.ToJson(b.Layout));
            b.UI.FocusTank(small);yield return new WaitForSeconds(.8f);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_06_CustomTank.png");yield return new WaitForSeconds(.2f);b.UI.Close();
            int donations=b.World.Save.visitors;float until=Time.time+70;while(b.World.Save.visitors==donations&&Time.time<until)yield return null;Check(b.World.Save.visitors>donations,"Live visitor navigates edited museum and donates");Check(b.World.Collect(out _),"Collect earned donations after layout edits");
            b.UI.Open();yield return new WaitForSeconds(.5f);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_06_ExpandedMuseum.png");
        }
        public static void Restart()
        {b=UnityEngine.Object.FindFirstObjectByType<AquariumBuilding>();results.Clear();bool pass=true;try{var expected=JsonUtility.FromJson<AquariumLayout>(File.ReadAllText("Temp/ASTRA06_expected.json"));Check(JsonUtility.ToJson(expected)==JsonUtility.ToJson(b.Layout),"Fresh Play Mode restores exact layout, styles, ownership, revision and expansion");Check(b.World.Tanks.Count(t=>!string.IsNullOrEmpty(t.definition.buildType))==b.Layout.objects.Count(o=>!o.stored&&b.Item(o.typeId)?.category==BuildCategory.Tanks),"Purchased tank visuals restored once");Check(b.Navigation.Validate(b.Layout),"Restored paths connected");Check(b.World.Data.kept.Where(f=>f.ownership==FishOwnership.Displayed).All(f=>b.World.Tanks.Any(t=>t.id==f.tankId)),"All displayed fish have valid live tanks");}catch(Exception e){pass=false;results.Add(e.ToString());}File.WriteAllText("Docs/ASTRA_06_RESTART_RESULTS.txt",(pass?"PASS ":"FAIL ")+DateTime.UtcNow.ToString("O")+"\n"+string.Join("\n",results));}
    }
}

